import{_ as a,o as e,a as _,b as i}from"./app.DKoEZOcr.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"随路量化与随路relu场景组合","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md","lastUpdated":1786949923000}'),r={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.md"};function n(p,t,o,c,b,s){return e(),_("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>随路量化与随路ReLU场景组合<span id="ZH-CN_TOPIC_0000002538071282"></span></h1><p>矩阵搬出支持多种随路量化与随路ReLU的组合，芯片支持的全量场景组合参考下表，接下来将对下表中的随路量化ReLU算法逐一介绍。</p><div data-filter="950,A3,910b"><p>随路量化与随路ReLU的组合情况如下表所示：</p><div data-filter="A3,910b"><p><strong>表1</strong> 随路量化与随路ReLU的组合表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><table><thead><tr><th>quantPre\\reluPre</th><th>no ReLU</th><th>Normal ReLU</th></tr></thead><tbody><tr><td>•REQ8<br>•DEQF16<br>•QF322B8_PRE</td><td>M1=QUANT_PRE[31:0]<br>M2=QUANT_PRE[31:0]<br>M1、M2均为量化参数</td><td>M1=QUANT_PRE[31:0]<br>M2=0<br>M1为量化参数、M2为Normal ReLU系数</td></tr><tr><td>•VREQ8<br>•VDEQF16<br>•VQF322B8_PRE</td><td>M1=Quant_PRE_ADDR[i][31:0]<br>M2=Quant_PRE_ADDR[i][31:0]<br>M1、M2均为量化参数，i为原始矩阵的列索引</td><td>M1=Quant_PRE_ADDR[i][31:0]<br>M2=0<br>M1为量化参数，M2为Normal ReLU系数，i为原始矩阵的列索引</td></tr></tbody></table></div><div data-filter="950"><p><strong>表2</strong> 随路量化与随路ReLU的组合表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><table><thead><tr><th>quantPre\\reluPre</th><th>no ReLU</th><th>Normal ReLU</th></tr></thead><tbody><tr><td>•REQ8<br>•DEQF16<br>•QF322B8_PRE<br>•QF322FP8_PRE<br>•QF322HIF8_PRE<br>•QF322HIF8_PRE_HYBRID<br>•QS322BF16_PRE<br>•QF322F16_PRE<br>•QF322BF16_PRE<br>•QF322F32_PRE</td><td>M1=QUANT_PRE[31:13]<br>M2=QUANT_PRE[31:13]<br>M1、M2均为量化参数</td><td>M1=QUANT_PRE[31:13]<br>M2=0<br>M1为量化参数、M2为Normal ReLU系数</td></tr><tr><td>•VREQ8<br>•VDEQF16<br>•VQF322B8_PRE<br>•VQF322FP8_PRE<br>•VQF322HIF8_PRE<br>•VQF322HIF8_PRE_HYBRID<br>•VQS322BF16_PRE<br>•VQF322F16_PRE<br>•VQF322BF16_PRE<br>•VQF322F32_PRE</td><td>M1=Quant_PRE_ADDR[i][31:13]<br>M2=Quant_PRE_ADDR[i][31:13]<br>M1、M2均为量化参数，i为原始矩阵的列索引</td><td>M1=Quant_PRE_ADDR[i][31:13]<br>M2=0<br>M1为量化参数，M2为Normal ReLU系数，i为原始矩阵的列索引</td></tr></tbody></table></div><p>注：M1为原始数据取值为正数时使用的随路系数，M2为原始数据取值为负数时使用的随路系数，N为右移位数，即量化系数；</p></div><p>以下为几种量化模式的Python示例代码跳转链接：</p><ul><li><p>(V)REQ8量化（(Vector)ReQuant (u)int8量化）与随路ReLU组合</p><p>将L0C Buffer上int32_t数据搬出过程中转换成int8_t/uint8_t，具体随路量化与ReLU算法的完整Python示例代码请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2gm/scripts/gen_data_s322s8.py">(V)REQ8量化算法</a>。</p></li><li><p>DEQF16与VDEQF16量化与随路ReLU组合</p><p>将L0C Buffer上int32_t数据搬出过程中转换成half（float16），具体随路量化与ReLU算法的完整Python示例代码请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2gm/scripts/gen_data_s322f16.py">(V)DEQF16算法</a>。</p></li><li><p>QF322B8_PRE与VQF322B8_PRE量化与随路ReLU组合</p><p>将L0C Buffer上float数据搬出过程中转换成int8_t/uint8_t，具体随路量化与ReLU算法的完整Python示例代码请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2gm/scripts/gen_data_f322s8.py">(V)QF322B8_PRE算法</a>。</p></li></ul></article></div>',1)])])}const R=a(r,[["render",n]]);export{u as __pageData,R as default};
